#!/usr/bin/env python3
import collections,json
from pathlib import Path
from datetime import datetime,timezone
from urllib.parse import urlsplit
R=Path(__file__).resolve().parent
latest={}
for line in (R/'checkpoint.jsonl').read_text().splitlines():
 try:r=json.loads(line);latest[r['id']]=r
 except (ValueError,KeyError):pass
items=list(latest.values())
for r in items:r.setdefault('body_completeness','not assessed');r.setdefault('document_form','not verified')
(R/'manifest.json').write_text(json.dumps(items,indent=2,ensure_ascii=False)+'\n')
c=collections.Counter(r['status'] for r in items);ident=collections.Counter(r.get('source_identity',{}).get('status') for r in items if r['status']=='file_obtained');domains=collections.Counter(urlsplit(a.get('url','')).netloc for r in items for a in r.get('attempts',[]) if a.get('http_status')==429 or a.get('outcome') in ('robots_429','host_deferred_429','host_deferred_429_previous_run'));blocked=collections.Counter(a.get('outcome') for r in items for a in r.get('attempts',[]) if a.get('outcome') not in ('http',None));
manual=[r for r in items if r['status']=='not_retrieved' or (r['status']=='file_obtained' and r.get('source_identity',{}).get('status')!='consistent')];(R/'manual_needed.txt').write_text('\n'.join(f"{r['id']} | {r['status']} | {r['title']} | {r.get('doi','')} | {r.get('source_identity',{}).get('reason','')}" for r in manual)+'\n')
lines=['# Legal full-text retrieval receipt','',f"Updated {datetime.now(timezone.utc).isoformat()}.",'',f"Source records accounted: {len(items)}; held skipped: {c['held_skipped']}; duplicate linked to another candidate: {c['duplicate_link']}; no file acquired: {c['not_retrieved']}; file acquired: {c['file_obtained']}.",f"For acquired files, first-page source identity consistent: {ident['consistent']}; unresolved: {ident['unresolved']}; conflict: {ident['conflict']}; unavailable: {ident['unavailable']}. A consistent identity is bounded first-page evidence, not proof of completeness or suitability. The unresolved and conflicting files require manual review and are not counted as confirmed full texts.",'', 'Source materials are stored outside Git under `/workspace/repos/builderbob/.writing-corpus-cache/fulltext/law/files/`. Per-item manifests preserve title, provider, full-text URL attempts, HTTP outcomes, final source URL, version/license if reported, size, hash, page count and identity assessment. Full text is not redistributed here. First-page title match alone is not identifier agreement. For legal articles, alternate versions, book/review merges, footnote-only appearances, published/corrected status and document boundaries also require review.','', 'The initial pass identified ordinary robots-file redirects as unavailable; a corrected subsequent pass followed them and retained prior attempts. The retrieval code respects robots exclusion, crawl-delay and request-rate (deferring delays over five seconds), limits four workers, paces each host, stops on HTTP 429, does not bypass denials, and does not use Unpaywall because no contact email was supplied. It tries source metadata public locations, publisher landing pages and advertised citation PDF links; HTML is not treated as a retrieved full article except one explicit official brief saved as unverified for review. First-pass Crossref metadata lookup stopped at 429; unresolved Hein-only items may need catalog lookup. No credentials or publisher access bypass were used.','',f"429-related hosts recorded: {dict(domains)}. Other logged deferred/denied attempt counts: {dict(blocked)}.",'', 'The `manual_needed.txt` list includes no-file and identity-unresolved records; held source records remain in the manifest rather than being silently discarded. Duplicate rows refer to the linked source record and are not additional acquired documents. DOI and version access, rights, actual body completeness and whether a full document is the requested legal form remain to be checked.']
(R/'summary.md').write_text('\n'.join(lines)+'\n')
print('records',len(items),'statuses',dict(c),'identities',dict(ident),'manual',len(manual))
